I’ve upload new version of function to convert:

{noformat}/**
 * Convert property types of an object based on a mapping.
 * @param object - the object to convert
 * @param mapping - the mapping of properties to types, supported types are: number, datetime
 * @param removeNulls - if true, remove properties that are null after conversion
 * @returns {*} - the converted object
 */
export default function convert(object, mapping, removeNulls=false) {
    const keys = Object.keys(object);
    keys.forEach((key) => {
        log('key', key, mapping[key])
        if (mapping[key] === "number") {
            object[key] = Number(object[key]);
        } else if (mapping[key] === "datetime") {
            log('convert', object[key], new Date(object[key]))
            object[key] = new Date(object[key]);
        }
        if (removeNulls && !object[key]) {
            delete object[key]
        }
    });
    return object;
}{noformat}

